#!/usr/bin/env node
/**
 * D-1 §12.1 — the disposable local pilot, run end to end.
 *
 * This harness:
 *   1. builds a throwaway source tree of MIXED REAL files (generated by
 *      ffmpeg's test sources, not text renamed .mov), plus nested bundles,
 *      overlapping leaf names, empty folders, and one large file;
 *   2. boots the PACKAGED app (release/mac-arm64/ferry.app) with isolated
 *      application data and with ffmpeg deliberately absent from PATH;
 *   3. drives scan -> destination -> plan -> preflight -> approve -> transfer
 *      -> receipt through the running app's own IPC bridge (CDP);
 *   4. verifies the destination INDEPENDENTLY, by walking source and
 *      destination with sha256 — ferry's own "succeeded" is the claim under
 *      test, not the evidence;
 *   5. restarts the packaged app against the same app data and re-reads the
 *      job and receipt;
 *   6. runs the same service contracts from the CLI.
 *
 * It prints a JSON report and writes it to --report. Nothing here is part of
 * the app build; it is a validation tool.
 *
 * usage:
 *   node docs/validation/d1/run-pilot.mjs [--root /tmp/d1-pilot]
 *     [--app <path to ferry.app .../MacOS/ferry>] [--ferry <path to CLI>]
 *     [--port 9224] [--keep]
 * Env overrides: D1_ROOT, D1_APP, D1_FERRY, D1_PORT.
 */
import { spawn, spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { createWriteStream, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync, openSync, readSync, closeSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, '..', '..', '..');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 ? process.argv[i + 1] : fallback;
}
const ROOT = resolve(arg('root', process.env.D1_ROOT ?? '/tmp/d1-pilot'));
const APP =
  arg('app', process.env.D1_APP) ??
  join(repoRoot, 'desktop', 'release', 'mac-arm64', 'ferry.app', 'Contents', 'MacOS', 'ferry');
const FERRY_CLI = arg('ferry', process.env.D1_FERRY) ?? join(repoRoot, '.venv', 'bin', 'ferry');
const PORT = Number(arg('port', process.env.D1_PORT ?? '9224'));
const KEEP = process.argv.includes('--keep');
const REPORT = arg('report', join(ROOT, 'report.json'));

const SOURCE = join(ROOT, 'source');
const DEST = join(ROOT, 'dest');
const DEST_CLI = join(ROOT, 'dest-cli');
const APPDATA = join(ROOT, 'appdata');
const CLI_DATA = join(ROOT, 'cli');

const LARGE_BYTES = 256 * 1024 * 1024; // 256 MiB — "large", not the D-2 10 GiB gate

function log(...a) {
  console.error('[d1]', ...a);
}

// ---------------------------------------------------------------------------
// fixtures
// ---------------------------------------------------------------------------

function ffmpeg(args, out) {
  const r = spawnSync('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-y', ...args, out], {
    encoding: 'utf8',
  });
  if (r.status !== 0) throw new Error(`ffmpeg failed for ${out}: ${r.stderr}`);
}

function sha256File(path) {
  const hash = createHash('sha256');
  const fd = openSync(path, 'r');
  const buf = Buffer.alloc(1024 * 1024);
  try {
    let n;
    while ((n = readSync(fd, buf, 0, buf.length, null)) > 0) hash.update(buf.subarray(0, n));
  } finally {
    closeSync(fd);
  }
  return hash.digest('hex');
}

async function writeLargeFile(path, bytes) {
  const stream = createWriteStream(path);
  const chunk = Buffer.alloc(1024 * 1024);
  for (let i = 0; i < chunk.length; i++) chunk[i] = (i * 31 + 7) & 0xff;
  let written = 0;
  while (written < bytes) {
    const n = Math.min(chunk.length, bytes - written);
    if (!stream.write(chunk.subarray(0, n))) await new Promise((r) => stream.once('drain', r));
    written += n;
  }
  await new Promise((r) => stream.end(r));
}

function walk(dir, base = dir) {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full, base));
    else if (entry.isFile()) out.push(relative(base, full));
  }
  return out;
}

function walkDirs(dir, base = dir) {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const full = join(dir, entry.name);
    out.push(relative(base, full));
    out.push(...walkDirs(full, base));
  }
  return out;
}

async function createFixtures() {
  rmSync(SOURCE, { recursive: true, force: true });
  rmSync(DEST, { recursive: true, force: true });
  mkdirSync(SOURCE, { recursive: true });
  mkdirSync(DEST, { recursive: true });

  const mk = (p) => mkdirSync(dirname(join(SOURCE, p)), { recursive: true });

  // Real H.264 movies (two leaf-name overlaps across DCIM/100 and DCIM/101).
  for (const rel of ['DCIM/100/A001.MOV', 'DCIM/101/A001.MOV', 'DCIM/100/A002.MOV']) {
    mk(rel);
    ffmpeg(
      ['-f', 'lavfi', '-i', 'testsrc=duration=1:size=640x360:rate=25', '-c:v', 'libx264', '-pix_fmt', 'yuv420p'],
      join(SOURCE, rel),
    );
  }
  // Real PCM audio.
  mk('AUDIO/interview.wav');
  ffmpeg(['-f', 'lavfi', '-i', 'sine=frequency=440:duration=1', '-c:a', 'pcm_s16le'], join(SOURCE, 'AUDIO/interview.wav'));
  // Real raster images; the JPEG pair overlaps by leaf name (Day1 / Day2).
  mk('GRAPHICS/hero.png');
  ffmpeg(['-f', 'lavfi', '-i', 'testsrc=duration=1:size=320x240:rate=1', '-frames:v', '1'], join(SOURCE, 'GRAPHICS/hero.png'));
  for (const rel of ['Day1/IMG_0001.JPG', 'Day2/IMG_0001.JPG']) {
    mk(rel);
    ffmpeg(['-f', 'lavfi', '-i', 'testsrc=duration=1:size=200x150:rate=1', '-frames:v', '1'], join(SOURCE, rel));
  }
  // A nested bundle with its own internal structure and a real image inside.
  mk('Bundles/Sample.photoslibrary/Masters/2025/IMG_0001.JPG');
  ffmpeg(
    ['-f', 'lavfi', '-i', 'testsrc=duration=1:size=180x120:rate=1', '-frames:v', '1'],
    join(SOURCE, 'Bundles/Sample.photoslibrary/Masters/2025/IMG_0001.JPG'),
  );
  mk('Bundles/Sample.photoslibrary/Database/photos.db');
  writeFileSync(join(SOURCE, 'Bundles/Sample.photoslibrary/Database/photos.db'), Buffer.from([0x53, 0x51, 0x4c, 0x69, 0x74, 0x65, 0x00, 0x01, 0x02, 0x03]));

  // Documents.
  mk('DOCS/notes.txt');
  writeFileSync(join(SOURCE, 'DOCS/notes.txt'), 'D-1 pilot notes\nline two\n');
  mk('DOCS/brief.pdf');
  writeFileSync(
    join(SOURCE, 'DOCS/brief.pdf'),
    '%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n2 0 obj<</Type/Pages/Kids[3 0 R]/Count 1>>endobj\n3 0 obj<</Type/Page/Parent 2 0 R/MediaBox[0 0 200 200]>>endobj\ntrailer<</Root 1 0 R>>\n%%EOF\n',
  );

  // Archives (real deflate / gzip streams).
  mk('ARCHIVES/payload.txt');
  writeFileSync(join(SOURCE, 'ARCHIVES/payload.txt'), 'archive payload\n');
  const zip = spawnSync('zip', ['-q', '-r', join(SOURCE, 'ARCHIVES/archive.zip'), 'payload.txt'], {
    cwd: join(SOURCE, 'ARCHIVES'),
    encoding: 'utf8',
  });
  if (zip.status !== 0) throw new Error(`zip failed: ${zip.stderr}`);
  const tar = spawnSync('tar', ['czf', join(SOURCE, 'ARCHIVES/data.tar.gz'), 'payload.txt'], {
    cwd: join(SOURCE, 'ARCHIVES'),
    encoding: 'utf8',
  });
  if (tar.status !== 0) throw new Error(`tar failed: ${tar.stderr}`);

  // A large binary.
  mk('large/plate.bin');
  await writeLargeFile(join(SOURCE, 'large/plate.bin'), LARGE_BYTES);

  // Empty folders (including a nested empty one).
  mkdirSync(join(SOURCE, 'Empty Folder/Nested Empty'), { recursive: true });

  const files = walk(SOURCE);
  const hashes = {};
  let totalBytes = 0;
  for (const rel of files) {
    const abs = join(SOURCE, rel);
    hashes[rel] = { sha256: sha256File(abs), bytes: statSync(abs).size };
    totalBytes += hashes[rel].bytes;
  }
  const emptyDirs = walkDirs(SOURCE).filter((d) => {
    const abs = join(SOURCE, d);
    return readdirSync(abs).length === 0;
  });
  return { files, hashes, totalBytes, emptyDirs };
}

// ---------------------------------------------------------------------------
// CDP
// ---------------------------------------------------------------------------

class Cdp {
  constructor(ws) {
    this.ws = ws;
    this.id = 0;
    this.pending = new Map();
    ws.addEventListener('message', (ev) => {
      const m = JSON.parse(ev.data);
      if (m.id && this.pending.has(m.id)) {
        const p = this.pending.get(m.id);
        this.pending.delete(m.id);
        m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
      }
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async eval(expression) {
    const r = await this.send('Runtime.evaluate', {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    if (r.exceptionDetails) {
      throw new Error(r.exceptionDetails.exception?.description ?? JSON.stringify(r.exceptionDetails));
    }
    return r.result.value;
  }
}

async function connect(port) {
  for (let i = 0; i < 120; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json/list`);
      const page = (await res.json()).find((t) => t.type === 'page');
      if (page) {
        const ws = new WebSocket(page.webSocketDebuggerUrl);
        await new Promise((r, j) => {
          ws.addEventListener('open', r, { once: true });
          ws.addEventListener('error', j, { once: true });
        });
        const cdp = new Cdp(ws);
        await cdp.send('Runtime.enable');
        return cdp;
      }
    } catch {
      /* not up yet */
    }
    await sleep(500);
  }
  throw new Error('CDP page target never appeared');
}

function launchApp({ appData, keepData = false }) {
  if (!keepData) rmSync(appData, { recursive: true, force: true });
  mkdirSync(appData, { recursive: true });
  const env = { ...process.env, PATH: '/usr/bin:/bin' }; // no ffmpeg
  const logFd = openSync(join(appData, 'app.log'), 'a');
  const child = spawn(APP, [`--remote-debugging-port=${PORT}`, `--user-data-dir=${appData}`], {
    env,
    stdio: ['ignore', logFd, logFd],
    detached: false,
  });
  return child;
}

/** The renderer can call before `ipcMain.handle` has run; retry that race. */
async function evalRetry(cdp, expression, tries = 80) {
  for (let i = 0; i < tries; i++) {
    try {
      return await cdp.eval(expression);
    } catch (e) {
      const msg = String(e);
      if (/No handler registered/.test(msg) && i < tries - 1) {
        await sleep(500);
        continue;
      }
      throw e;
    }
  }
  throw new Error('evalRetry exhausted');
}

const waitJob = async (cdp, id) => {
  for (let i = 0; i < 1200; i++) {
    const job = await cdp.eval(`window.ferry.job.get(${JSON.stringify(id)})`);
    if (['succeeded', 'failed', 'cancelled', 'needs_attention'].includes(job.state)) return job;
    await sleep(500);
  }
  throw new Error('job never reached a terminal state');
};

async function runFlow(cdp) {
  const status = await evalRetry(cdp, 'window.ferry.app.getStatus()');
  const doctor = await evalRetry(cdp, 'window.ferry.app.doctor()');

  const destination = await cdp.eval(
    `window.ferry.destination.save({ name: ${JSON.stringify('D1 Pilot Destination')}, path: ${JSON.stringify(DEST)} })`,
  );
  const created = await cdp.eval(
    `window.ferry.inventory.create({ path: ${JSON.stringify(SOURCE)}, label: ${JSON.stringify('D1 Pilot Source')} })`,
  );
  let inventory;
  for (let i = 0; i < 2400; i++) {
    inventory = await cdp.eval(`window.ferry.inventory.status(${created.inventoryId})`);
    if (inventory.status !== 'scanning') break;
    await sleep(250);
  }
  if (inventory.status !== 'complete') throw new Error(`inventory: ${JSON.stringify(inventory)}`);

  const plan = await cdp.eval(
    `window.ferry.transfer.planCreate({ destinationId: ${destination.id}, inventoryIds: [${created.inventoryId}] })`,
  );
  const startedPre = await cdp.eval(`window.ferry.transfer.preflightStart(${JSON.stringify(plan.id)})`);
  let pre;
  for (let i = 0; i < 2400; i++) {
    pre = await cdp.eval(`window.ferry.transfer.preflightStatus(${startedPre.id})`);
    if (pre.status !== 'running') break;
    await sleep(250);
  }
  if (pre.status !== 'passed') throw new Error(`preflight: ${JSON.stringify(pre)}`);

  const approved = await cdp.eval(
    `window.ferry.transfer.planApprove(${JSON.stringify(plan.id)}, ${JSON.stringify(plan.fingerprint)})`,
  );
  const started = await cdp.eval(
    `window.ferry.transfer.start(${JSON.stringify(plan.id)}, ${JSON.stringify(plan.fingerprint)})`,
  );
  const job = await waitJob(cdp, started.job.id);
  const receipt = await cdp.eval(`window.ferry.transfer.receipt(${JSON.stringify(plan.id)})`);
  const entryPage = await cdp.eval(
    `window.ferry.transfer.planEntries(${JSON.stringify(plan.id)}, { limit: 1000 })`,
  );

  return { status, doctor, destination, inventory, plan, pre, approved, started, job, receipt, entryPage };
}

// ---------------------------------------------------------------------------
// independent verification
// ---------------------------------------------------------------------------

function independentVerify(sourceHashes, entryPage, destRoot, emptyDirs = [], receiptEntries = []) {
  // relPath -> destRelPath from the plan, augmented by the receipt ledger for
  // entries the plan page did not carry (the empty folder is one).
  const mapping = {};
  for (const e of entryPage.entries) mapping[e.relPath] = { destRelPath: e.destRelPath, action: e.action };
  for (const e of receiptEntries) {
    if (mapping[e.relPath] === undefined && e.destRelPath) {
      mapping[e.relPath] = { destRelPath: e.destRelPath, action: 'copy' };
    }
  }

  const results = [];
  for (const [rel, meta] of Object.entries(sourceHashes)) {
    const m = mapping[rel];
    if (!m) {
      results.push({ source: rel, status: 'not-in-plan' });
      continue;
    }
    if (m.action !== 'copy') {
      results.push({ source: rel, status: 'excluded', action: m.action });
      continue;
    }
    const destAbs = join(destRoot, m.destRelPath);
    if (!existsSync(destAbs)) {
      results.push({ source: rel, status: 'missing-at-destination', destRelPath: m.destRelPath });
      continue;
    }
    const dHash = sha256File(destAbs);
    const dBytes = statSync(destAbs).size;
    results.push({
      source: rel,
      destRelPath: m.destRelPath,
      status: dHash === meta.sha256 && dBytes === meta.bytes ? 'verified-identical' : 'MISMATCH',
      sourceSha256: meta.sha256,
      destSha256: dHash,
      bytes: meta.bytes,
    });
  }
  // Anything at the destination the plan did not put there.
  const planned = new Set(Object.values(mapping).map((m) => m.destRelPath));
  const extra = walk(destRoot).filter((rel) => !planned.has(rel));

  // Every empty source directory must have a ledger entry and exist at dest.
  const dirChecks = emptyDirs.map((rel) => {
    const m = mapping[rel];
    const destAbs = m ? join(destRoot, m.destRelPath) : null;
    const present = destAbs !== null && existsSync(destAbs) && statSync(destAbs).isDirectory();
    return {
      source: rel,
      destRelPath: m?.destRelPath ?? null,
      status: present ? 'directory-recreated' : 'directory-missing',
    };
  });

  // Ledger reconciliation: every receipt entry is committed, and the ledger
  // size is exactly the regular files plus the empty directories.
  const committed = receiptEntries.filter((e) => e.state === 'committed').length;
  return {
    results,
    extra,
    mapping,
    dirChecks,
    ledger: {
      entries: receiptEntries.length,
      committed,
      files: Object.keys(sourceHashes).length,
      emptyDirs: emptyDirs.length,
      reconciled: receiptEntries.length === Object.keys(sourceHashes).length + emptyDirs.length,
    },
  };
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

function runCli(args, cwd) {
  const r = spawnSync(FERRY_CLI, [...args, '--json'], {
    cwd,
    env: { ...process.env, PATH: '/usr/bin:/bin:/opt/homebrew/bin' },
    encoding: 'utf8',
  });
  const out = (r.stdout || '').trim();
  let parsed = null;
  try {
    parsed = JSON.parse(out);
  } catch {
    parsed = out;
  }
  return { status: r.status, parsed, stderr: (r.stderr || '').slice(0, 2000) };
}

function cliFlow(report) {
  rmSync(CLI_DATA, { recursive: true, force: true });
  rmSync(DEST_CLI, { recursive: true, force: true });
  mkdirSync(CLI_DATA, { recursive: true });
  mkdirSync(DEST_CLI, { recursive: true });
  const db = join(CLI_DATA, 'ferry.db');
  const base = ['--db', db];
  const steps = {};
  const dest = runCli([...base, 'destination', 'save', '--name', 'D1 CLI Destination', '--path', DEST_CLI], CLI_DATA);
  steps['destination save'] = dest;
  const inv = runCli([...base, 'inventory', 'create', '--path', SOURCE, '--label', 'D1 CLI Source'], CLI_DATA);
  steps['inventory create'] = inv;
  const plan = runCli(
    [...base, 'plan', 'create', '--destination-id', String(dest.parsed.id), '--inventory', String(inv.parsed.inventoryId ?? inv.parsed.id)],
    CLI_DATA,
  );
  steps['plan create'] = plan;
  const pre = runCli([...base, 'preflight', 'run', String(plan.parsed.id)], CLI_DATA);
  steps['preflight run'] = pre;
  const approve = runCli(
    [...base, 'plan', 'approve', String(plan.parsed.id), '--fingerprint', String(plan.parsed.fingerprint)],
    CLI_DATA,
  );
  steps['plan approve'] = approve;
  const start = runCli(
    [...base, 'transfer', 'start', String(plan.parsed.id), '--fingerprint', String(plan.parsed.fingerprint)],
    CLI_DATA,
  );
  steps['transfer start'] = start;
  const receipt = runCli([...base, 'transfer', 'receipt', String(plan.parsed.id)], CLI_DATA);
  steps['transfer receipt'] = receipt;
  const entries = runCli([...base, 'plan', 'entries', String(plan.parsed.id), '--limit', '1000'], CLI_DATA);
  steps['plan entries'] = entries;
  report.cli = {
    steps: Object.fromEntries(
      Object.entries(steps).map(([k, v]) => [k, { status: v.status, parsed: v.parsed, stderr: v.stderr }]),
    ),
    planId: plan.parsed?.id,
  };
  return { plan: plan.parsed, entries: entries.parsed ?? { entries: [] } };
}

// ---------------------------------------------------------------------------

async function main() {
  const report = { startedAt: new Date().toISOString(), provenance: {} };
  if (!existsSync(APP)) throw new Error(`packaged app not found: ${APP}`);
  report.provenance.app = APP;
  report.provenance.appBundle = APP.replace(/\/Contents\/MacOS\/ferry$/, '');
  report.provenance.appSha256 = sha256File(APP);
  report.provenance.sidecarSha256 = existsSync(join(repoRoot, 'desktop', 'sidecar', 'arm64', 'ferry-service'))
    ? sha256File(join(repoRoot, 'desktop', 'sidecar', 'arm64', 'ferry-service'))
    : null;
  report.provenance.gitCommit = spawnSync('git', ['-C', repoRoot, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).stdout.trim();
  report.provenance.gitDescribe = spawnSync('git', ['-C', repoRoot, 'log', '-1', '--format=%h %s'], { encoding: 'utf8' }).stdout.trim();
  report.provenance.node = process.version;

  log('creating fixtures in', SOURCE);
  const fixtures = await createFixtures();
  report.fixtures = {
    fileCount: fixtures.files.length,
    totalBytes: fixtures.totalBytes,
    emptyDirs: fixtures.emptyDirs,
    files: fixtures.hashes,
  };
  log(`fixtures: ${fixtures.files.length} files, ${fixtures.totalBytes} bytes`);

  log('launching packaged app (PATH without ffmpeg)');
  let child = launchApp({ appData: APPDATA });
  let cdp = await connect(PORT);

  log('running scan -> ... -> receipt in the packaged app');
  const flow = await runFlow(cdp);
  report.packagedApp = {
    sidecarVersion: flow.status.sidecarVersion,
    protocolVersion: flow.status.protocolVersion,
    capabilities: flow.status.capabilities.filter((c) => c.startsWith('transfer.')),
    ffmpegPresent: flow.doctor.tools.find((t) => t.name === 'ffmpeg')?.present ?? null,
    appDataDir: flow.doctor.appDataDir,
    dbPath: flow.doctor.dbPath,
    destinationId: flow.destination.id,
    inventoryId: flow.inventory.id,
    inventoryCounts: {
      fileCount: flow.inventory.fileCount,
      dirCount: flow.inventory.dirCount,
      totalBytes: flow.inventory.totalBytes,
      errorCount: flow.inventory.errorCount,
    },
    planId: flow.plan.id,
    planFingerprint: flow.plan.fingerprint,
    planTotals: {
      totalFiles: flow.plan.totalFiles,
      totalBytes: flow.plan.totalBytes,
      conflicts: flow.plan.conflictCount,
      blocking: flow.plan.blockingCount,
      exclusions: flow.plan.exclusionCount,
    },
    preflightStatus: flow.pre.status,
    jobId: flow.job.id,
    jobState: flow.job.state,
    receiptFinalState: flow.receipt.finalState,
    receiptSummary: flow.receipt.receipt?.actual ?? null,
    receiptRaw: flow.receipt.receipt,
  };

  log('independent sha256 verification of the destination');
  const verify = independentVerify(
    fixtures.hashes,
    flow.entryPage,
    DEST,
    fixtures.emptyDirs,
    flow.receipt.receipt?.entries ?? [],
  );
  const tally = {};
  for (const r of verify.results) tally[r.status] = (tally[r.status] ?? 0) + 1;
  report.verification = {
    tally,
    extra: verify.extra,
    dirChecks: verify.dirChecks,
    ledger: verify.ledger,
    results: verify.results,
  };

  log('restarting the packaged app against the same app data');
  child.kill('SIGTERM');
  await sleep(2000);
  spawnSync('pkill', ['-f', 'ferry.app/Contents/MacOS/ferry']);
  spawnSync('pkill', ['-f', 'ferry-service']);
  await sleep(1500);
  child = launchApp({ appData: APPDATA, keepData: true });
  cdp = await connect(PORT);
  const afterRestart = await evalRetry(
    cdp,
    `(async () => {
       const status = await window.ferry.app.getStatus();
       const jobs = await window.ferry.job.list();
       const receipt = await window.ferry.transfer.receipt(${JSON.stringify(flow.plan.id)});
       return {
         sidecarVersion: status.sidecarVersion,
         jobStates: jobs.jobs.map((j) => j.state),
         receiptFinalState: receipt.finalState,
         heading: document.querySelector('h1')?.textContent ?? null,
       };
     })()`,
  );
  report.restart = afterRestart;

  log('running the CLI flow against the same service contracts');
  const cliResult = cliFlow(report);
  const cliReceipt = report.cli.steps['transfer receipt']?.parsed;
  const cliReceiptEntries = cliReceipt?.receipt?.entries ?? cliReceipt?.entries ?? [];
  const cliVerify = independentVerify(fixtures.hashes, cliResult.entries, DEST_CLI, fixtures.emptyDirs, cliReceiptEntries);
  report.cliVerification = {
    tally: cliVerify.results.reduce((acc, r) => ((acc[r.status] = (acc[r.status] ?? 0) + 1), acc), {}),
    extra: cliVerify.extra,
    dirChecks: cliVerify.dirChecks,
    ledger: cliVerify.ledger,
  };

  child.kill('SIGTERM');
  spawnSync('pkill', ['-f', 'ferry.app/Contents/MacOS/ferry']);
  spawnSync('pkill', ['-f', 'ferry-service']);
  await sleep(1000);

  report.finishedAt = new Date().toISOString();
  writeFileSync(REPORT, JSON.stringify(report, null, 2));
  if (!KEEP) {
    // keep the report; the throwaway trees can be removed by the operator
  }
  console.log(JSON.stringify({ report: REPORT, tally: report.verification.tally, extra: report.verification.extra, cliTally: report.cliVerification.tally, jobState: report.packagedApp.jobState, restart: report.restart }, null, 2));
}

main().catch((err) => {
  console.error('[d1] FAILED:', err);
  spawnSync('pkill', ['-f', 'ferry.app/Contents/MacOS/ferry']);
  process.exit(1);
});
